import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { portableFinishAttention, finishObservationPath } from '../../../src/portable-finish-diagnostics.mjs';
import { sha256, formatJson } from '../../../src/files.mjs';
const root = await fs.mkdtemp(path.join(os.tmpdir(), 'wi0247-qa-portable-'));
const directory = path.join(root, '.ai-org/artifacts/WI-0001');
await fs.mkdir(directory, { recursive: true });
const observations = [];
try {
  for (const mode of ['failed-visible', 'local-failure-dominates', 'wrong-binding',
    'missing-operation', 'numeric-operation', 'missing-candidate', 'missing-plan', 'missing-recovery-authority',
    'result-work-item-mismatch', 'result-operation-mismatch', 'numeric-observation-time']) {
    for (const file of await fs.readdir(directory)) await fs.unlink(path.join(directory, file));
    try {
      const request = { schema_version: 'temple.lean-finish-request/v1', work_item_id: 'WI-0001',
        agent_id: 'agent-builder', principal_id: 'human', claim_id: 'claim-fixture', position: 'developer',
        completed: ['Bounded QA fixture'], evidence: ['docs/qa.md'], unresolved: [],
        ...(mode === 'missing-operation' ? {} : { operation_id: mode === 'numeric-operation' ? 42 : 'qa-op' }),
        ...(mode === 'missing-candidate' ? {} : { candidate_revision: 'a'.repeat(40) }) };
      const result = { candidate_revision: request.candidate_revision,
        work_item_id: mode === 'result-work-item-mismatch' ? 'WI-0002' : request.work_item_id,
        operation_id: mode === 'result-operation-mismatch' ? 'other-op' : request.operation_id,
        receipt: `.ai-org/artifacts/WI-0001/finish-${request.operation_id}.json`,
        ...(mode === 'missing-plan' ? {} : { plan_digest: 'b'.repeat(64) }) };
      const relative = finishObservationPath('WI-0001', request.operation_id);
      const receipt = { schema_version: 'temple.lean-finish-receipt/v1', request, applied_at: new Date().toISOString(),
        request_digest: sha256(formatJson(request)), result, diagnostics_observation: relative };
      const bytes = formatJson(receipt);
      await fs.writeFile(path.join(directory, `finish-${request.operation_id}.json`), bytes);
      const observation = { schema_version: 'temple.finish-observation/v1', authority: 'observation-only',
        work_item_id: request.work_item_id, operation_id: request.operation_id,
        candidate_revision: request.candidate_revision, request_digest: receipt.request_digest,
        plan_digest: result.plan_digest, receipt_sha256: mode === 'wrong-binding' ? '0'.repeat(64) : sha256(bytes),
        status: mode === 'failed-visible' ? 'failed' : 'passed', errors: [], observed_at: mode === 'numeric-observation-time' ? 2026 : new Date().toISOString(),
        ...(mode === 'missing-recovery-authority' ? {} : { recovery_authority: 'origin-checkout-journal-required' }) };
      await fs.writeFile(path.join(root, relative), formatJson(observation));
      const local = mode === 'local-failure-dominates' ? [{ operation_key: 'WI-0001/qa-op', status: 'failed' }] : [];
      const attention = await portableFinishAttention(root, local);
      observations.push({ mode, rejected: false, attention: attention.map(row => ({ status: row.status, source: row.source, local_journal_available: row.local_journal_available })) });
    } catch (error) { observations.push({ mode, rejected: true, error: error.message }); }
  }
} finally { await fs.rm(root, { recursive: true, force: true }); }
console.log(JSON.stringify({ agent_id: 'agent-lulu', observations, owned_temp_cleanup: true }, null, 2));

import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import { fixture, cli, git, itemState } from '../../../test/helpers/lean-delivery-fixture.mjs';
import { finishLeanWorkItem } from '../../../src/lean-finish.mjs';
import { withProjectMutationLock } from '../../../src/project.mjs';
import { completionDoctorPassed } from '../../../src/completion-diagnostics.mjs';

const observations = [];
const finish = (f, dryRun = false) => withProjectMutationLock(f.target,
  () => finishLeanWorkItem(f.target, { ...f.request, dryRun }),
  { leanDeliveryOperation: `${f.item.id}/${f.request.operationId}` });

for (const mode of ['dirty-instruction', 'reverted-source-history', 'untracked-source', 'administrative-positive']) {
  const f = await fixture();
  try {
    const integrationPath = path.join(f.target, '.ai-org/project/repository-integration.json');
    const integration = JSON.parse(await fs.readFile(integrationPath));
    await fs.writeFile(integrationPath, JSON.stringify({ ...integration, status: 'confirmed', source: 'human-confirmed', summary: 'QA synthetic fixture', change_isolation: 'not-required', review_gate: 'not-required', recorded_at: new Date().toISOString(), recorded_by: 'human' }, null, 2) + '\n');
    git(f.target, ['add', '.']); git(f.target, ['commit', '-m', 'Confirm synthetic integration policy']);
    f.request.revision = git(f.target, ['rev-parse', 'HEAD']);
    f.request.position = 'developer';
    const first = await finish(f);
    if (!first.success) throw Error(`Fixture developer completion failed: ${JSON.stringify(first.diagnostics)}`);
    git(f.target, ['add', '.']); git(f.target, ['commit', '-m', 'Retain delivery administration']);
    f.request = { ...f.request, position: 'quality_evaluator', operationId: `qa-${mode}`,
      agentId: f.qualityAgent, completed: [], evidence: [], judgment: 'pass',
      testEvidence: ['docs/qa-review.md'], leanCloseout: ['docs/qa-review.md'] };
    f.request.claimId = JSON.parse(cli(['work-item', 'claim', f.target, '--work-item', f.item.id,
      '--agent-id', f.qualityAgent, '--principal-id', 'human', '--base-revision', f.request.revision,
      '--branch', 'main', '--json']).stdout).item.claim.id;
    await fs.writeFile(path.join(f.target, 'docs/qa-review.md'), '# Independent fixture review\nExpected output observed.\n');
    if (mode === 'dirty-instruction') {
      await fs.appendFile(path.join(f.target, 'TEMPLE.md'), '\nUncommitted instruction drift control.\n');
    } else if (mode === 'reverted-source-history') {
      const file = path.join(f.target, 'app.mjs'); const original = await fs.readFile(file);
      await fs.appendFile(file, '\n// Intervening product commit\n');
      git(f.target, ['add', 'app.mjs']); git(f.target, ['commit', '-m', 'Unrelated product change']);
      await fs.writeFile(file, original);
      git(f.target, ['add', 'app.mjs']); git(f.target, ['commit', '-m', 'Revert unrelated product change']);
    } else if (mode === 'untracked-source') {
      await fs.writeFile(path.join(f.target, 'unrelated.mjs'), 'export const unreviewed = true;\n');
    }
    let outcome;
    try { const result = await finish(f, true); outcome = { returned: true, status: result.status, lifecycle_status: result.mutation?.status }; }
    catch (error) { outcome = { returned: false, error: error.message }; }
    observations.push({ mode, expected: mode === 'administrative-positive' ? 'ready' : 'reject', observed: outcome,
      resulting_state: (await itemState(f)).state, candidate_unchanged: true });
  } finally { await f.cleanup(); }
}

const info = { id: 'collaboration_validation', code: 'COLLABORATION_REAL_VALIDATION_NOT_PASSED', status: 'warn' };
const doctor = { healthy: true, summary: { pass: 1, fail: 0, warn: 1 }, checks: [info] };
assert.equal(completionDoctorPassed(doctor), true);
for (const check of [{ ...info, code: 'UNKNOWN' }, { ...info, id: 'other' }, { ...info, status: 'fail' }])
  assert.equal(completionDoctorPassed({ ...doctor, checks: [check] }), false);
assert.equal(completionDoctorPassed({ ...doctor, checks: [info, { id: 'other', status: 'warn' }], summary: { pass: 1, fail: 0, warn: 2 } }), false);
observations.push({ mode: 'warning-classification-counterexamples', observed: 'pass' });
console.log(JSON.stringify({ candidate: git(process.cwd(), ['rev-parse', 'HEAD']), agent_id: 'agent-lulu', observations, owned_temp_cleanup: true }, null, 2));

